// The four branch points are 2 CM points of discriminant -52 and 2 of discriminant -132.
// The model independently predicts they are defined over Q(sqrt(13)) and Q(sqrt(-11)).
// Those fields must appear inside the corresponding ring class fields. Check it.
for d in [-52, -132] do
    K := QuadraticField(d);
    O := sub< MaximalOrder(K) | 1 >;  // placeholder
    h := ClassNumber(BinaryQuadraticForms(d));
    printf "discriminant %o : CM field Q(sqrt(%o)), class number h = %o\n", d, Squarefree(Abs(d))*Sign(d), h;
    // genus field: generated by the square roots of the prime discriminants dividing d
    pds := [];
    for p in PrimeDivisors(Abs(d)) do
        if p eq 2 then continue; end if;
        pd := (p mod 4 eq 1) select p else -p;
        Append(~pds, pd);
    end for;
    rem := d div (&*pds);
    if rem ne 1 then Append(~pds, rem); end if;
    printf "   prime discriminants: %o  -> genus field Q(%o)\n", pds, [ Sprintf("sqrt(%o)", x) : x in pds ];
    sub2 := { };
    for S in Subsets(SequenceToSet(pds)) do
        if #S eq 0 then continue; end if;
        Include(~sub2, Squarefree(Abs(&*S)) * Sign(&*S));
    end for;
    printf "   quadratic subfields of the genus field: %o\n", Sort(SetToSequence(sub2));
end for;
printf "\nthe model predicts Q(sqrt(13)) for one pair and Q(sqrt(-11)) for the other.\n";
print "CERT6 DONE";
